### Skrip JavaScript untuk Melindungi Preferensi Pengguna

```javascript
// Fungsi untuk mengenkripsi data menggunakan algoritma sederhana (contoh: XOR)
function encrypt(data) {
    const key = 'rahasia'; // Ganti dengan kunci enkripsi yang kuat dan rahasia
    let encrypted = '';
    for (let i = 0; i < data.length; i++) {
        encrypted += String.fromCharCode(data.charCodeAt(i) ^ key.charCodeAt(i % key.length));
    }
    return encrypted;
}

// Fungsi untuk mendekripsi data
function decrypt(encryptedData) {
    const key = 'rahasia'; // Pastikan kunci yang sama dengan yang digunakan untuk enkripsi
    let decrypted = '';
    for (let i = 0; i < encryptedData.length; i += 2) {
        decrypted += String.fromCharCode(encryptedData.charCodeAt(i) ^ key.charCodeAt(i % key.length));
    }
    return decrypted;
}

// Fungsi untuk menyimpan preferensi pengguna
function savePreferences(preferences) {
    const encryptedPreferences = encrypt(JSON.stringify(preferences));
    localStorage.setItem('userPreferences', encryptedPreferences);
}

// Fungsi untuk memuat preferensi pengguna
function loadPreferences() {
    const encryptedPreferences = localStorage.getItem('userPreferences');
    if (encryptedPreferences) {
        const decryptedPreferences = decrypt(encryptedPreferences);
        return JSON.parse(decryptedPreferences);
    }
    return {};
}

// Contoh penggunaan
const userPreferences = {
    theme: 'dark',
    language: 'en',
    notifications: true
};

// Menyimpan preferensi
savePreferences(userPreferences);

// Memuat preferensi
const loadedPreferences = loadPreferences();
console.log(loadedPreferences);
```

